<section class="comments-section"><div class="detail-section-heading"><div><span class="eyebrow">Conversa boa</span><h2>Comentários</h2></div><span class="comments-count">{{ $this->comentarios()->count() }}</span></div>@auth<form wire:submit="comentar" class="comment-form"><textarea wire:model="novoComentario" rows="3" placeholder="Conte o que achou ou deixe uma dica..."></textarea>@error('novoComentario')<small class="form-error">{{ $message }}</small>@enderror<button type="submit" class="button">Publicar comentário <span>→</span></button></form>@else<div class="login-comment-note"><p>Quer compartilhar sua experiência?</p><a href="{{ route('login') }}">Entre na sua conta para comentar →</a></div>@endauth<div class="comment-list">@forelse($this->comentarios() as $comment)<article class="comment-item"><div class="comment-avatar">{{ mb_strtoupper(mb_substr($comment->user->name, 0, 1)) }}</div><div class="comment-content"><div class="comment-heading"><strong>{{ $comment->user->name }}</strong><time>{{ $comment->created_at->diffForHumans() }}</time></div>@if($editandoId === $comment->id)<textarea wire:model="textoEdicao" rows="2"></textarea><div class="comment-actions"><button wire:click="salvarEdicao" type="button">Salvar</button><button wire:click="$set('editandoId', null)" type="button">Cancelar</button></div>@else<p>{{ $comment->conteudo }}</p>@auth @if(auth()->id() === $comment->user_id)<div class="comment-actions"><button wire:click="iniciarEdicao({{ $comment->id }})" type="button">Editar</button><button wire:click="excluir({{ $comment->id }})" wire:confirm="Excluir este comentário?" type="button">Excluir</button></div>@endif @endauth @endif</div></article>@empty<p class="comments-empty">Ainda não há comentários. Seja o primeiro a contar como ficou!</p>@endforelse</div></section>
